import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.iXqqCa-C.js";const l="/images/agent-square.webp",g=JSON.parse('{"title":"游玩入门","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/quick-start.md","filePath":"guide/agent/quick-start.md","lastUpdated":1793501934000}'),o={name:"guide/agent/quick-start.md"};function n(s,a,d,h,c,u){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="游玩入门" tabindex="-1">游玩入门 <a class="header-anchor" href="#游玩入门" aria-label="Permalink to &quot;游玩入门&quot;">​</a></h1><p>智能体是阈界人格社区的 AI 角色聊天功能。你可以和别人发布的角色聊天，也可以<a href="/guide/agent/create">创作自己的角色</a>。</p><h2 id="开始之前-先有一份对话风格" tabindex="-1">开始之前：先有一份对话风格 <a class="header-anchor" href="#开始之前-先有一份对话风格" aria-label="Permalink to &quot;开始之前：先有一份对话风格&quot;">​</a></h2><p>对话风格决定角色怎么说话（语气、人称、句长、是否有动作描写）。发送消息前必须为会话选择一份风格，可以自己<a href="/guide/agent/styles#创建风格">创建</a>，也可以在广场把别人发布的风格「加入我的列表」。没有可用风格时，会话页会引导你去广场挑选。</p><h2 id="从广场找角色" tabindex="-1">从广场找角色 <a class="header-anchor" href="#从广场找角色" aria-label="Permalink to &quot;从广场找角色&quot;">​</a></h2><p>进入「智能体 → 广场」，可以：</p><ul><li>按<strong>推荐、热度、评分、最新</strong>排序浏览所有已发布角色。</li><li>用搜索框按<strong>名称、简介、作者</strong>找角色（多个关键词用空格分隔）。</li><li>查看角色卡片：头像、名称、简介、创作者、评分、会话次数、对话次数等。</li></ul><p><img src="'+l+'" alt="智能体广场"></p><p>角色详情页显示「提示词规模」（各部分的字符数）、评分分布和<a href="#参与评价">评价</a>。</p><h2 id="开始聊天" tabindex="-1">开始聊天 <a class="header-anchor" href="#开始聊天" aria-label="Permalink to &quot;开始聊天&quot;">​</a></h2><ol><li>在角色详情页点击「开始聊天」，确认后创建新会话。</li><li>在「对话风格」标签页选择一份风格。</li><li>发送第一条消息。角色设置了开场白时，会话创建后会自动出现。</li></ol><p>历史会话都在侧栏「消息」页的「智能体」标签页中，点击即可继续对话，有新消息的会话会显示未读数。详见<a href="/guide/agent/chat">聊天与会话</a>。</p><h2 id="参与评价" tabindex="-1">参与评价 <a class="header-anchor" href="#参与评价" aria-label="Permalink to &quot;参与评价&quot;">​</a></h2><p>在角色详情页可以打分（0～5 星）并写评价。评价以帖子形式发布，可见范围可选「公开」或「仅关注者」。</p><h2 id="草稿测试与社区游玩" tabindex="-1">草稿测试与社区游玩 <a class="header-anchor" href="#草稿测试与社区游玩" aria-label="Permalink to &quot;草稿测试与社区游玩&quot;">​</a></h2><ul><li><strong>草稿测试</strong>：在「创作」页测试角色草稿时产生的会话，只有你自己能看到。</li><li><strong>社区游玩</strong>：和已发布角色聊天产生的会话。</li></ul><p>两者功能相同，删除会话时都会一并删除便签，见<a href="/guide/agent/memory">记忆</a>。</p>',17)])])}const _=e(o,[["render",n]]);export{g as __pageData,_ as default};
